css:
.renewalsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1f2d23;
    background: linear-gradient(160deg, #f1f7ee 0%, #e7f1e4 100%);
    border-radius: 18px;
}

.renewalsim-container * {
    box-sizing: border-box;
}

.renewalsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #1e5b3a 0%, #2f7d4f 55%, #4a9d63 100%);
    color: #f3fbf2;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(30, 91, 58, 0.30);
}

.renewalsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.renewalsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #cdeccd;
    background: rgba(255, 255, 255, 0.12);
    padding: 5px 14px;
    border-radius: 999px;
}

.renewalsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #e4f3e2;
}

.renewalsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2a5a3c;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.renewalsim-period-counter #currentDay,
.renewalsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #1e5b3a;
}

.renewalsim-round-name {
    background: #d4ead6;
    color: #1e5b3a;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.renewalsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a4410;
    background: #fcebdc;
    padding: 4px 12px;
    border-radius: 999px;
}

.renewalsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.renewalsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #d9e8d8;
    box-shadow: 0 4px 14px rgba(30, 91, 58, 0.07);
    border-top: 4px solid #4a9d63;
}

.renewalsim-card-model { border-top-color: #2f7d4f; }
.renewalsim-card-funding { border-top-color: #b8860b; }
.renewalsim-card-worklife { border-top-color: #2f6fb0; }
.renewalsim-card-engagement { border-top-color: #8a5cc0; }

.renewalsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #5e7a64;
}

.renewalsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #1e5b3a;
}

.renewalsim-card-model .renewalsim-value { color: #2f7d4f; }
.renewalsim-card-funding .renewalsim-value { color: #b8860b; }
.renewalsim-card-worklife .renewalsim-value { color: #2f6fb0; }
.renewalsim-card-engagement .renewalsim-value { color: #8a5cc0; }

.renewalsim-sublabel {
    font-size: 0.76rem;
    color: #6f8b74;
    line-height: 1.35;
}

.renewalsim-funding-short .renewalsim-value { color: #c0392b; }
.renewalsim-funding-closed .renewalsim-value { color: #2f7d4f; }

.renewalsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #1e5b3a;
    color: #eaf6ea;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.renewalsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
}

.renewalsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #4a9d63;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(30, 91, 58, 0.05);
}

.renewalsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.renewalsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #1e5b3a;
    margin-bottom: 6px;
}

.renewalsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #324a38;
}

.renewalsim-briefing-text strong { color: #2f7d4f; }
.renewalsim-briefing-text em { color: #9a4410; font-style: italic; }

.renewalsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #d9e8d8;
    box-shadow: 0 4px 14px rgba(30, 91, 58, 0.06);
}

.renewalsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #1e5b3a;
    border-bottom: 2px solid #e4f0e2;
    padding-bottom: 8px;
}

.renewalsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #284a31;
    margin: 14px 0 6px;
}

.renewalsim-container select,
.renewalsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #bcd6bd;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f6fbf5;
    color: #1f2d23;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.renewalsim-container select:focus,
.renewalsim-container input[type="number"]:focus {
    outline: none;
    border-color: #2f7d4f;
    box-shadow: 0 0 0 3px rgba(47, 125, 79, 0.16);
}

.renewalsim-container select option {
    background-color: #ffffff;
    color: #1f2d23;
}

.renewalsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #2f7d4f;
}

.renewalsim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #2a5a3c;
    margin-top: 4px;
}

.renewalsim-range-readout span:last-child {
    color: #b8860b;
    font-weight: 800;
}

.renewalsim-hint {
    font-size: 0.8rem;
    color: #6f8b74;
    margin-top: 4px;
    line-height: 1.4;
}

.renewalsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.renewalsim-container .btn-primary {
    background: linear-gradient(135deg, #2f7d4f 0%, #4a9d63 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(47, 125, 79, 0.28);
}

.renewalsim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.renewalsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #bcd6bd;
    color: #5e7a64;
}

.renewalsim-coach {
    background: #1e5b3a;
    color: #eaf6ea;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(30, 91, 58, 0.22);
}

.renewalsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #9fd6a6;
    margin-bottom: 8px;
}

.renewalsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.renewalsim-coach-body strong { color: #ffd98a; }
.renewalsim-coach-body em { color: #ffc1ad; font-style: italic; }

.renewalsim-history,
.renewalsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #d9e8d8;
    box-shadow: 0 4px 14px rgba(30, 91, 58, 0.06);
}

.renewalsim-history h3,
.renewalsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #1e5b3a;
}

.renewalsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #284a31;
}

.renewalsim-container table#usfHistoryTable th {
    background: #eaf4e9;
    color: #1e5b3a;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d4e6d3;
}

.renewalsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef5ed;
}

.renewalsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f8fbf7;
}

.renewalsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .renewalsim-container {
        padding: 14px;
    }
    .renewalsim-header h1 {
        font-size: 1.7rem;
    }
    .renewalsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .renewalsim-value {
        font-size: 2rem;
    }
    .renewalsim-clock {
        margin-left: 0;
    }
    .renewalsim-period-counter {
        font-size: 0.88rem;
    }
    .renewalsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .renewalsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* v1.1.0 completion-message card (appended; self-contained) */
.renewalsim-cm { background:#f6f8f6; color:#1a2420; border-radius:14px; padding:22px 24px; max-width:640px; margin:0 auto; font-family:inherit; box-shadow:0 8px 30px rgba(26,36,32,0.18); }
.renewalsim-cm-head { text-align:center; border-bottom:1px solid #d3e0d8; padding-bottom:14px; margin-bottom:16px; }
.renewalsim-cm-title { font-size:13px; letter-spacing:.08em; text-transform:uppercase; color:#4f6a5e; font-weight:700; }
.renewalsim-cm-scorewrap { margin:8px 0 2px; }
.renewalsim-cm-score { font-size:52px; font-weight:800; color:#1f7a52; line-height:1; }
.renewalsim-cm-score-max { font-size:20px; color:#7f978b; font-weight:600; }
.renewalsim-cm-grade { font-size:19px; font-weight:700; color:#1a2420; margin-top:4px; }
.renewalsim-cm-badges { margin-top:12px; display:flex; flex-wrap:wrap; gap:8px; justify-content:center; }
.renewalsim-cm-badge { font-size:12px; font-weight:700; padding:4px 11px; border-radius:999px; }
.renewalsim-cm-met { background:#cfe8d8; color:#136b45; }
.renewalsim-cm-fail { background:#f2ddd7; color:#9c3a2b; }
.renewalsim-cm-metrics { display:flex; flex-wrap:wrap; gap:12px; justify-content:center; margin-bottom:16px; }
.renewalsim-cm-metric { background:#e6efe8; border-radius:10px; padding:12px 16px; min-width:100px; text-align:center; }
.renewalsim-cm-metric-val { font-size:22px; font-weight:800; color:#22483a; }
.renewalsim-cm-metric-lbl { font-size:11px; letter-spacing:.05em; text-transform:uppercase; color:#4f6a5e; margin-top:3px; }
.renewalsim-cm-insights { background:#e6efe8; border-radius:10px; padding:14px 18px; }
.renewalsim-cm-insights-title { font-size:12px; letter-spacing:.06em; text-transform:uppercase; color:#4f6a5e; font-weight:700; margin-bottom:8px; }
.renewalsim-cm-insights ul { margin:0; padding-left:18px; }
.renewalsim-cm-insights li { font-size:14px; line-height:1.5; color:#22483a; margin-bottom:7px; }

