(function() {
    'use strict';

    class RenewalAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `The Renewal Venture`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Reviva SAS).
            this.START_FUNDING = 520;        // EUR k soft-committed
            this.MIN_CLOSE = 750;            // EUR k lead-fund minimum close
            this.SEED_TARGET = 900;          // EUR k full seed
            this.START_STAKE = 62;           // % founder stake pre-round
            this.CASH_BUFFER = 350;          // EUR k
            this.MONTHLY_BURN = 70;          // EUR k / month
            this.TRUE_RUNWAY = 5;            // months (350 / 70)

            // Concept truths.
            this.TRUE_CONSTRAINT = `focus`;
            this.TRUE_TOPMODEL = `ownbrand`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    model: 20,
                    funding: this.START_FUNDING,
                    worklife: 22,
                    engagement: 25,
                    stake: this.START_STAKE,
                    runway: this.TRUE_RUNWAY,
                    roundClosed: false,
                    controlLost: false,
                    missionDrift: false,
                    modelHistory: [20],
                    fundingHistory: [this.START_FUNDING],
                    worklifeHistory: [22],
                    engagementHistory: [25],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            // Seeded defaults are a MIDDLING / neutral mix — never the textbook-correct play.
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    constraint: `cash`,
                    runwayCalc: 5,
                    topModel: `whitelabel`,
                    inclusion: 50,
                    modelChoice: `hedge`,
                    financing: `ceoclause`,
                    control: 50,
                    ops: `automate`,
                    leadership: `delegating`,
                    hours: 65,
                    fund: 50,
                    pitch: `growth`,
                    inclusionPitch: `both`,
                    metric: `revenue`,
                    conviction: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const con = document.getElementById(`constraintInput`);
                const rw = document.getElementById(`runwayInput`);
                const tm = document.getElementById(`topModelInput`);
                const inc = document.getElementById(`inclusionInput`);
                if (con) decisions.constraint = con.value;
                if (tm) decisions.topModel = tm.value;
                if (rw) decisions.runwayCalc = parseFloat(rw.value);
                if (inc) decisions.inclusion = parseInt(inc.value, 10);
                if (!Number.isFinite(decisions.runwayCalc) || decisions.runwayCalc < 0 || decisions.runwayCalc > 24) {
                    warn(`warn_runway_range`); return false;
                }
                if (!Number.isFinite(decisions.inclusion) || decisions.inclusion < 0 || decisions.inclusion > 100) {
                    warn(`warn_inclusion_range`); return false;
                }
            } else if (round === 2) {
                const mc = document.getElementById(`modelChoiceInput`);
                const fin = document.getElementById(`financingInput`);
                const ctrl = document.getElementById(`controlInput`);
                if (mc) decisions.modelChoice = mc.value;
                if (fin) decisions.financing = fin.value;
                if (ctrl) decisions.control = parseInt(ctrl.value, 10);
                if (!Number.isFinite(decisions.control) || decisions.control < 0 || decisions.control > 100) {
                    warn(`warn_control_range`); return false;
                }
            } else if (round === 3) {
                const op = document.getElementById(`opsInput`);
                const ld = document.getElementById(`leadershipInput`);
                const hr = document.getElementById(`hoursInput`);
                const fd = document.getElementById(`fundInput`);
                if (op) decisions.ops = op.value;
                if (ld) decisions.leadership = ld.value;
                if (hr) decisions.hours = parseFloat(hr.value);
                if (fd) decisions.fund = parseInt(fd.value, 10);
                if (!Number.isFinite(decisions.hours) || decisions.hours < 35 || decisions.hours > 80) {
                    warn(`warn_hours_range`); return false;
                }
                if (!Number.isFinite(decisions.fund) || decisions.fund < 0 || decisions.fund > 100) {
                    warn(`warn_fund_range`); return false;
                }
            } else if (round === 4) {
                const pt = document.getElementById(`pitchInput`);
                const ip = document.getElementById(`inclusionPitchInput`);
                const me = document.getElementById(`metricInput`);
                const cv = document.getElementById(`convictionInput`);
                if (pt) decisions.pitch = pt.value;
                if (ip) decisions.inclusionPitch = ip.value;
                if (me) decisions.metric = me.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let modelDelta = 0, fundingDelta = 0, worklifeDelta = 0, engagementDelta = 0;
            let stakeDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Separate the presenting €230k gap from the root constraint (focus + sustainability).
                switch (d.constraint) {
                    case `focus`: modelDelta += 12; worklifeDelta += 6; engagementDelta += 4; coachKey = `coach_r1_focus`; break;
                    case `cash`: modelDelta -= 4; coachKey = `coach_r1_cash`; break;
                    case `sales`: modelDelta -= 8; worklifeDelta -= 6; engagementDelta -= 6; coachKey = `coach_r1_sales`; break;
                    case `valuation`: modelDelta -= 6; fundingDelta -= 10; coachKey = `coach_r1_valuation`; break;
                }

                // True runway = 350 / 70 = 5 months. Getting the arithmetic right is table stakes.
                if (Math.abs(d.runwayCalc - this.TRUE_RUNWAY) <= 0.25) {
                    modelDelta += 5;
                } else {
                    modelDelta -= 6; coachKey = `coach_r1_runway`;
                }

                // Rank own-brand inclusive resale first (margin + mission-fit); refusing to rank is paralysis.
                switch (d.topModel) {
                    case `ownbrand`: modelDelta += 10; if (d.constraint === `focus`) coachKey = `coach_r1_sharp`; break;
                    case `whitelabel`: modelDelta += 2; break;
                    case `subscription`: modelDelta -= 4; break;
                    case `allthree`: modelDelta -= 12; coachKey = `coach_r1_allthree`; break;
                }

                // Inclusion as cost structure (high) vs. story (low).
                if (d.inclusion >= 60) { modelDelta += 4; engagementDelta += 6; }
                else if (d.inclusion <= 25) { modelDelta -= 4; engagementDelta -= 4; coachKey = `coach_r1_inclusionlow`; }

                summaryKey = (d.constraint === `focus` && d.topModel === `ownbrand`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Choose ONE model (Common Error 1: optionality paralysis).
                switch (d.modelChoice) {
                    case `ownbrand`: modelDelta += 12; engagementDelta += 4; coachKey = `coach_r2_ownbrand`; break;
                    case `whitelabel`: modelDelta += 6; engagementDelta -= 2; coachKey = `coach_r2_whitelabel`; break;
                    case `subscription`: modelDelta += 2; coachKey = `coach_r2_subscription`; break;
                    case `hedge`: modelDelta -= 14; coachKey = `coach_r2_hedge`; break;
                }

                // Financing stack to the €750k close — and what it costs in control (Common Error 2).
                switch (d.financing) {
                    case `negotiate`:
                        // +€250k AND mission lock / longer CEO-clause runway: closes strongly, control held.
                        fundingDelta += 250; modelDelta += 6; stakeDelta -= 14; coachKey = `coach_r2_negotiate`; break;
                    case `loan`:
                        // €150k non-dilutive + small angel top-up: closes, control well protected, adds debt service.
                        fundingDelta += 230; worklifeDelta -= 2; stakeDelta -= 6; coachKey = `coach_r2_loan`; break;
                    case `ceoclause`:
                        // +€250k as offered, no conditions: solves cash, signs away the founder.
                        fundingDelta += 250; stakeDelta -= 18; ds.controlLost = true; coachKey = `coach_r2_ceoclause`; break;
                    case `cut`:
                        // Small angel bridge + burn cut: control kept but the round does NOT close.
                        fundingDelta += 80; worklifeDelta += 2; stakeDelta -= 3; coachKey = `coach_r2_cut`; break;
                }

                // Pricing control, not just cash — protections negotiated soften dilution.
                if (d.control >= 60) { stakeDelta += 6; modelDelta += 3; }
                else if (d.control <= 25) { stakeDelta -= 4; coachKey = `coach_r2_nocontrol`; }

                const willClose = (ds.funding + fundingDelta) >= this.MIN_CLOSE;
                summaryKey = (d.modelChoice === `ownbrand` && willClose) ? `sum_r2_good` : (d.modelChoice === `hedge` ? `sum_r2_paralysis` : `sum_r2_weak`);
            } else if (round === 3) {
                // Remove the weekend-shift attrition driver (Common Error 3: growth on the team's back).
                switch (d.ops) {
                    case `hire`: engagementDelta += 16; worklifeDelta += 8; modelDelta += 2; coachKey = `coach_r3_hire`; break;
                    case `automate`: engagementDelta += 6; worklifeDelta += 4; modelDelta += 4; coachKey = `coach_r3_automate`; break;
                    case `cap`: engagementDelta += 8; worklifeDelta += 6; modelDelta -= 4; coachKey = `coach_r3_cap`; break;
                    case `status`: engagementDelta -= 16; worklifeDelta -= 8; modelDelta -= 4; coachKey = `coach_r3_status`; break;
                }

                // Leadership approach — and what the founder stops doing.
                switch (d.leadership) {
                    case `distributed`: worklifeDelta += 10; engagementDelta += 8; coachKey = (d.ops === `hire`) ? `coach_r3_combo` : coachKey; break;
                    case `delegating`: worklifeDelta += 8; engagementDelta += 4; break;
                    case `owner`: worklifeDelta -= 10; engagementDelta -= 4; coachKey = `coach_r3_owner`; break;
                }

                // A work-life target is only real if it is funded (Common Error 4: costless target).
                const ambitious = d.hours <= 50;
                const funded = d.fund >= 60;
                if (ambitious && funded) {
                    worklifeDelta += 14;
                } else if (ambitious && !funded) {
                    worklifeDelta -= 10; coachKey = `coach_r3_costless`;
                } else if (!ambitious && funded) {
                    worklifeDelta += 6;
                } else {
                    worklifeDelta -= 2;
                }

                summaryKey = (d.ops !== `status` && ambitious && funded) ? `sum_r3_good` : (d.ops === `status` || (ambitious && !funded) ? `sum_r3_team` : `sum_r3_weak`);
            } else if (round === 4) {
                // Integrate into a consistent pitch (Common Error 5: inclusion as a slide).
                switch (d.pitch) {
                    case `coherent`: modelDelta += 8; engagementDelta += 4; coachKey = `coach_r4_coherent`; break;
                    case `growth`: modelDelta -= 4; engagementDelta -= 6; worklifeDelta -= 4; coachKey = `coach_r4_growth`; break;
                    case `mission`: modelDelta -= 2; fundingDelta -= 0; coachKey = `coach_r4_mission`; break;
                }

                // Inclusion: cost structure or story? (the Chair's core point).
                switch (d.inclusionPitch) {
                    case `model`: modelDelta += 10; engagementDelta += 8; coachKey = (d.pitch === `coherent`) ? `coach_r4_inclmodel` : coachKey; break;
                    case `both`: modelDelta += 4; engagementDelta += 3; break;
                    case `slide`: modelDelta -= 8; engagementDelta -= 8; ds.missionDrift = true; coachKey = `coach_r4_inclslide`; break;
                }

                // The 12-month commitment metric.
                switch (d.metric) {
                    case `balanced`: modelDelta += 6; worklifeDelta += 6; engagementDelta += 4; break;
                    case `revenue`: worklifeDelta -= 4; engagementDelta -= 2; coachKey = `coach_r4_revenue`; break;
                    case `raise`: modelDelta -= 2; stakeDelta -= 2; coachKey = `coach_r4_raise`; break;
                }

                // Conviction nudges model viability.
                modelDelta += Math.round((d.conviction - 60) / 10);

                summaryKey = (d.pitch === `coherent` && d.inclusionPitch !== `slide` && d.metric === `balanced`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Apply deltas with floors/caps (0–100 KPIs; funding/stake/runway tracked separately).
            ds.model = Math.max(0, Math.min(100, ds.model + modelDelta));
            ds.worklife = Math.max(0, Math.min(100, ds.worklife + worklifeDelta));
            ds.engagement = Math.max(0, Math.min(100, ds.engagement + engagementDelta));
            ds.funding = Math.max(0, Math.round(ds.funding + fundingDelta));
            ds.stake = Math.max(0, Math.min(100, Math.round((ds.stake + stakeDelta) * 10) / 10));

            // Runway: hiring/cutting burn shift it; closing the round extends it materially.
            if (round === 2) {
                if (d.financing === `cut`) ds.runway = Math.round((ds.runway + 4) * 10) / 10;
            }
            if (round === 3 && d.ops === `hire`) ds.runway = Math.max(0, Math.round((ds.runway - 0.5) * 10) / 10);
            if (ds.funding >= this.MIN_CLOSE && !ds.roundClosed) {
                ds.roundClosed = true;
                ds.runway = 18; // a closed round funds the second workshop + D2C platform
            }

            ds.modelHistory.push(Math.round(ds.model));
            ds.fundingHistory.push(Math.round(ds.funding));
            ds.worklifeHistory.push(Math.round(ds.worklife));
            ds.engagementHistory.push(Math.round(ds.engagement));

            // v1.1.0: persist composite for instructor gradebook (results_utils.php Ruta 1).
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = this._composite(ds);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                model: Math.round(ds.model),
                modelDelta: Math.round(modelDelta),
                funding: Math.round(ds.funding),
                fundingDelta: Math.round(fundingDelta),
                worklife: Math.round(ds.worklife),
                worklifeDelta: Math.round(worklifeDelta),
                engagement: Math.round(ds.engagement),
                engagementDelta: Math.round(engagementDelta),
                stake: ds.stake,
                roundClosed: ds.roundClosed,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtMoney(valueK) {
            // valueK is in thousands of EUR. Locale-aware EUR formatting.
            const lang = (window.mySimulation && window.mySimulation.language) || `en`;
            const v = Number(valueK);
            if (lang === `es`) {
                if (v >= 1000) {
                    const m = (v / 1000).toFixed(1).replace(`.`, `,`);
                    return m + ` M€`;
                }
                return Math.round(v) + `k€`;
            }
            if (v >= 1000) {
                return `€` + (v / 1000).toFixed(1) + `M`;
            }
            return `€` + Math.round(v) + `k`;
        }

