        getChartData(state) {
            const ds = state.domainState;
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            const labels = ds.modelHistory.map((_, i) => (i === 0 ? t(`chart_start`) : t(`chart_round_prefix`) + i));
            return {
                renewalChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.modelHistory },
                        { data: ds.worklifeHistory },
                        { data: ds.engagementHistory },
                        { data: ds.fundingHistory }
                    ]
                }
            };
        }

        _composite(ds) {
            // v1.1.0 single source of truth - verbatim v1.0.0 formula (scoring unchanged).
            const model = Math.round(ds.model);
            const worklife = Math.round(ds.worklife);
            const engagement = Math.round(ds.engagement);
            const funding = Math.round(ds.funding);
            let control = Math.max(0, Math.min(100, Math.round((ds.stake - 38) / (this.START_STAKE - 38) * 100)));
            if (ds.controlLost) control = Math.min(control, 40);
            return Math.round(model * 0.30 + worklife * 0.20 + engagement * 0.20 + Math.min(100, (funding / this.MIN_CLOSE) * 100) * 0.18 + control * 0.12);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const model = Math.round(ds.model);
            const worklife = Math.round(ds.worklife);
            const engagement = Math.round(ds.engagement);
            const funding = Math.round(ds.funding);

            const closed = funding >= this.MIN_CLOSE;
            const humanOk = worklife >= 55 && engagement >= 55;
            // Founder control as a scored KPI: stake 38%→0, 62%→100; the 'professional CEO'
            // clause (controlLost) caps it so pricing-only-cash (Common Error 2) measurably costs the score.
            let control = Math.max(0, Math.min(100, Math.round((ds.stake - 38) / (this.START_STAKE - 38) * 100)));
            if (ds.controlLost) control = Math.min(control, 40);
            const controlOk = ds.stake >= 46 && !ds.controlLost;
            const composite = this._composite(ds);

            let performanceKey = `grade_collapsed`;
            // Top tier requires founder control held — signing away the CEO seat drops you a tier even when funded & sustainable.
            if (closed && humanOk && controlOk && composite >= 72) performanceKey = `grade_renewal`;
            else if (closed && humanOk && !controlOk && composite >= 68) performanceKey = `grade_sidelined`;
            else if (closed && humanOk) performanceKey = `grade_sustainable`;
            else if (closed && ds.controlLost) performanceKey = `grade_sidelined`;
            else if (closed && !humanOk) performanceKey = `grade_teamback`;
            else if (funding > this.START_FUNDING + 100) performanceKey = `grade_short`;
            const performance = window.mySimulation.t(performanceKey);
            const met = closed && humanOk && controlOk && composite >= 72;

            const insights = [];
            if (closed && humanOk) insights.push(window.mySimulation.t(`insight_renewal`));
            else if (closed && ds.controlLost) insights.push(window.mySimulation.t(`insight_control`));
            else if (closed && !humanOk) insights.push(window.mySimulation.t(`insight_team`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (ds.missionDrift) insights.push(window.mySimulation.t(`insight_mission`));
            if (worklife < 45) insights.push(window.mySimulation.t(`insight_burnout`));
            if (engagement < 45) insights.push(window.mySimulation.t(`insight_attrition`));
            if (ds.stake >= 50) insights.push(window.mySimulation.t(`insight_keptcontrol`));
            if (closed && humanOk && model >= 70) insights.push(window.mySimulation.t(`insight_focused`));

            return {
                model: model,
                worklife: worklife,
                engagement: engagement,
                funding: funding,
                stake: ds.stake,
                control: control,
                controlOk: controlOk,
                closed: closed,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                met: met,
                humanOk: humanOk,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            const s = summary || {};
            const score = (s.composite != null) ? s.composite : 0;
            const grade = s.performance || (s.performanceKey ? t(s.performanceKey) : ``);
            const badges = [];
            badges.push(`<span class="renewalsim-cm-badge ` + (s.met ? `renewalsim-cm-met` : `renewalsim-cm-fail`) + `">` + (s.met ? t(`cm_met`) : t(`cm_not_met`)) + `</span>`);
            if (s.closed === false) badges.push(`<span class="renewalsim-cm-badge renewalsim-cm-fail">` + t(`cm_fail_close`) + `</span>`);
            if (s.humanOk === false) badges.push(`<span class="renewalsim-cm-badge renewalsim-cm-fail">` + t(`cm_fail_human`) + `</span>`);
            if (s.controlOk === false) badges.push(`<span class="renewalsim-cm-badge renewalsim-cm-fail">` + t(`cm_fail_control`) + `</span>`);
            const kpi = (label, val) => `<div class="renewalsim-cm-metric"><div class="renewalsim-cm-metric-val">` + val + `</div><div class="renewalsim-cm-metric-lbl">` + label + `</div></div>`;
            const kpis = kpi(t(`cm_model`), (s.model != null ? Math.round(s.model) : 0))
                + kpi(t(`cm_funding`), (s.funding != null ? this._fmtMoney(s.funding) : `-`))
                + kpi(t(`cm_worklife`), (s.worklife != null ? Math.round(s.worklife) : 0))
                + kpi(t(`cm_engagement`), (s.engagement != null ? Math.round(s.engagement) : 0))
                + kpi(t(`cm_index`), score + `/100`);
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `<div class="renewalsim-cm">`
                + `<div class="renewalsim-cm-head"><div class="renewalsim-cm-title">` + t(`cm_title`) + `</div>`
                + `<div class="renewalsim-cm-scorewrap"><span class="renewalsim-cm-score">` + score + `</span><span class="renewalsim-cm-score-max">/100</span></div>`
                + `<div class="renewalsim-cm-grade">` + grade + `</div>`
                + `<div class="renewalsim-cm-badges">` + badges.join(``) + `</div></div>`
                + `<div class="renewalsim-cm-metrics">` + kpis + `</div>`
                + `<div class="renewalsim-cm-insights"><div class="renewalsim-cm-insights-title">` + t(`cm_insights_title`) + `</div><ul>` + insights + `</ul></div>`
                + `</div>`;
        }

