            if (ds.controlLost && ds.stake < 48) return window.mySimulation.t(`hint_control`);
            if (ds.engagement < 35) return window.mySimulation.t(`hint_engagement`);
            if (ds.worklife < 35 && state.currentPeriod >= 3) return window.mySimulation.t(`hint_worklife`);
